// ws_client.js
// WebSocket tunnel adapter for net_helper.
// This module owns the raw WebSocket connection and exposes a
// net_helper-compatible { tx, id } pair so it can be plugged
// into any net node as a tunnel for the backend.

const wsUrl = 'ws://localhost:8080'
const id    = 'backend'   // the remote peer's address in the hierarchy

let ws
const _listeners = []  // multiple net nodes can bind to incoming messages

const ws_client = {
  id: 'backend',
  // tx: called by a net node to send a message over the wire
  tx (M) {
    if (!ws || ws.readyState !== window.WebSocket.OPEN) {
      console.warn(`[ws_client] WebSocket not ready — dropping "${M.type}" (state: ${ws ? ws.readyState : 'null'})`)
      return
    }
    ws.send(JSON.stringify(M))
  },
  // bind: registers an rx handler — multiple components can bind without overwriting each other
  bind (rx) {
    if (typeof rx === 'function' && !_listeners.includes(rx)) {
      _listeners.push(rx)
    }
  },
  get status () { return ws ? ws.readyState : null },
  OPEN: typeof window !== 'undefined' && window.WebSocket ? window.WebSocket.OPEN : 1
}

function connect () {
  try {
    if (typeof window === 'undefined' || !window.WebSocket) return

    ws = new window.WebSocket(wsUrl)

    ws.onopen = () => {
      console.log('[ws_client] ✅ Connected to', wsUrl)
    }

    ws.onclose = () => {
      console.log('[ws_client] ❌ Disconnected — retrying in 2s...')
      setTimeout(connect, 2000)
    }

    ws.onerror = (err) => {
      console.error('[ws_client] ⚠️ WebSocket error:', err)
    }

    ws.onmessage = (ev) => {
      if (_listeners.length === 0) return
      try {
        const M = JSON.parse(ev.data)
        for (const rx of _listeners) {
          try { rx(M) } catch (err) { console.error('[ws_client] listener error:', err) }
        }
      } catch (err) {
        console.error('[ws_client] failed to parse incoming message:', err)
      }
    }
  } catch (err) {
    console.error('[ws_client] connect error:', err)
  }
}

connect()

module.exports = ws_client
